import 'package:flutter/material.dart';
import '../../services/local_environment.dart';
class ServersPage extends StatefulWidget{const ServersPage({super.key});@override State<ServersPage> createState()=>_ServersPageState();}
class _ServersPageState extends State<ServersPage>{final e=LocalEnvironment.instance;final port=TextEditingController(text:'8080');@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Servers')),body:ListView(padding:const EdgeInsets.all(18),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('HTTP SERVER',style:TextStyle(letterSpacing:1.5,color:Colors.white60)),const SizedBox(height:12),Text(e.webRunning?'Running · 127.0.0.1:${e.port}':'Stopped',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:20),TextField(controller:port,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Port',border:OutlineInputBorder())),const SizedBox(height:12),FilledButton(onPressed:()=>_toggle(),child:Text(e.webRunning?'Stop server':'Start server'))])),const SizedBox(height:12),const Card(child:ListTile(leading:Icon(Icons.code),title:Text('PHP runtime'),subtitle:Text('Not installed — PHP files are not executed.'))),const Card(child:ListTile(leading:Icon(Icons.info_outline),title:Text('Network binding'),subtitle:Text('Bound to 127.0.0.1 only; LAN access is not enabled.')))]));Future<void> _toggle()async{try{if(e.webRunning){await e.stopServer();}else{final n=int.parse(port.text);if(n<1024||n>65535)throw const FormatException('Port must be 1024–65535');await e.startServer(requestedPort:n);}setState((){});}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x')));setState((){});}}}
